"""Braille tutorial data, generated by native liblouis (UEB tables), never typed by hand.

Writes content/tutorials/braille-g1.json and content/tutorials/braille-g2.json.
Every braille string in the output is exactly what liblouis returns; the EXPECT
values below are only a cross-check (the build fails if liblouis disagrees, so a
liblouis upgrade that changes output is noticed, not silently shipped).

Run inside the bridgify-api image (it has liblouis 3.39 + python bindings):
  docker run --rm --user "$(id -u):$(id -g)" \
    -v "$PWD/tools-content/letters:/scripts:ro" -v "$PWD/content/tutorials:/out" \
    bridgify-api /venv/bin/python -I /scripts/braille_build.py /out
"""

from __future__ import annotations

import json
import sys
from pathlib import Path

import louis

G1 = ["unicode.dis", "en-ueb-g1.ctb"]
G2 = ["unicode.dis", "en-ueb-g2.ctb"]


def tr(table, text: str) -> str:
    return louis.translateString(table, text)


def dots(cells: str) -> list[str]:
    """'⠃⠁' -> ['12', '1'] (raised dots per cell, '' for a blank cell)."""
    out = []
    for ch in cells:
        v = ord(ch) - 0x2800
        assert 0 <= v <= 0xFF, f"not a braille cell: {ch!r}"
        out.append("".join(str(i + 1) for i in range(8) if v >> i & 1))
    return out


def strip(full: str, prefix: str = "", suffix: str = "") -> str:
    assert full.startswith(prefix) and full.endswith(suffix), (full, prefix, suffix)
    return full[len(prefix): len(full) - len(suffix) if suffix else None]


# --------------------------------------------------------------------------- grade 1

def grade1() -> dict:
    letters = []
    for c in "abcdefghijklmnopqrstuvwxyz":
        b = tr(G1, c)
        assert len(b) == 1, (c, b)
        letters.append({"char": c, "braille": b, "dots": dots(b)})
    a_to_j = {l["char"]: l["braille"] for l in letters[:10]}

    numbers = []
    num_sign = strip(tr(G1, "1"), suffix=a_to_j["a"])
    for d in "1234567890":
        b = tr(G1, d)
        letter = "abcdefghij"["1234567890".index(d)]
        assert b == num_sign + a_to_j[letter], (d, b)
        numbers.append({"char": d, "braille": b, "dots": dots(b), "letter": letter})

    cap = strip(tr(G1, "A"), suffix=a_to_j["a"])
    capword = strip(tr(G1, "ABC"), suffix="".join(a_to_j[c] for c in "abc"))
    g1ind = strip(tr(G2, "b"), suffix=a_to_j["b"])  # standalone b in grade 2 needs it
    indicators = [
        {"id": "capital", "name": "Capital letter", "braille": cap, "dots": dots(cap),
         "example": {"text": "A", "braille": tr(G1, "A")}},
        {"id": "capital-word", "name": "Capitalised word", "braille": capword, "dots": dots(capword),
         "example": {"text": "ABC", "braille": tr(G1, "ABC")}},
        {"id": "number", "name": "Number sign", "braille": num_sign, "dots": dots(num_sign),
         "example": {"text": "10", "braille": tr(G1, "10")}},
        {"id": "grade1", "name": "Grade 1 indicator", "braille": g1ind, "dots": dots(g1ind),
         "example": {"text": "b", "braille": tr(G2, "b")},
         "note": "In contracted (grade 2) braille, marks a letter that would otherwise read as a word."},
    ]
    EXPECT = {"capital": "⠠", "capital-word": "⠠⠠", "number": "⠼", "grade1": "⠰"}
    for i in indicators:
        assert i["braille"] == EXPECT[i["id"]], i

    a, b = a_to_j["a"], a_to_j["b"]
    # (char, name, sample text, prefix, suffix): the mark is what is left after stripping
    PUNCT = [
        (".", "Full stop", "a.", a, ""),
        (",", "Comma", "a,", a, ""),
        ("?", "Question mark", "a?", a, ""),
        ("!", "Exclamation mark", "a!", a, ""),
        ("'", "Apostrophe", "a'b", a, b),
        ("-", "Hyphen", "a-b", a, b),
        ("—", "Dash", "a—b", a, b),
        (":", "Colon", "a:", a, ""),
        (";", "Semicolon", "a;", a, ""),
        ("“", "Opening double quote", "“a”", "", None),
        ("”", "Closing double quote", "“a”", None, ""),
        ("(", "Opening bracket", "(a)", "", None),
        (")", "Closing bracket", "(a)", None, ""),
        ("/", "Slash", "a/b", a, b),
        ("@", "At sign", "a@b", a, b),
        ("&", "Ampersand", "a&b", a, b),
        ("$", "Dollar sign", "$5", "", "⠼⠑"),
        ("%", "Percent sign", "5%", "⠼⠑", ""),
    ]
    EXPECT_P = {".": "⠲", ",": "⠂", "?": "⠦", "!": "⠖", "'": "⠄", "-": "⠤", "—": "⠠⠤", ":": "⠒",
                ";": "⠆", "“": "⠦", "”": "⠴", "(": "⠐⠣", ")": "⠐⠜", "/": "⠸⠌", "@": "⠈⠁",
                "&": "⠈⠯", "$": "⠈⠎", "%": "⠨⠴"}
    punctuation = []
    for ch, name, text, pre, suf in PUNCT:
        full = tr(G1, text)
        if pre is None:  # closing half of a pair: drop the opening mark + the letter
            mark = full[full.index(a) + 1:]
        elif suf is None:  # opening half: everything before the letter
            mark = full[: full.index(a)]
        else:
            mark = strip(full, pre, suf)
        assert mark == EXPECT_P[ch], (ch, full, mark)
        punctuation.append({"char": ch, "name": name, "braille": mark, "dots": dots(mark),
                            "example": {"text": text, "braille": full}})

    return {
        "title": "Braille alphabet (UEB grade 1, uncontracted)",
        "code": "UEB",
        "grade": 1,
        "generator": {"tool": "liblouis", "version": louis.version(), "tables": ",".join(G1)},
        "source": "liblouis",
        "dotsFormat": "one string per cell listing its raised dots, e.g. '125' = dots 1, 2 and 5",
        "letters": letters,
        "numbers": numbers,
        "indicators": indicators,
        "punctuation": punctuation,
    }


# --------------------------------------------------------------------------- grade 2

CATEGORIES = [
    {"id": "alphabetic-wordsign", "name": "Alphabetic wordsigns",
     "note": "A single letter standing alone as a whole word."},
    {"id": "strong-contraction", "name": "Strong contractions",
     "note": "One cell for and, for, of, the, with: as words and inside words."},
    {"id": "strong-wordsign", "name": "Strong wordsigns",
     "note": "The ch, sh, th, wh, ou, st cells standing alone as a whole word."},
    {"id": "strong-groupsign", "name": "Strong groupsigns",
     "note": "One cell for a group of letters inside a word."},
    {"id": "lower-wordsign", "name": "Lower wordsigns",
     "note": "Cells using only dots 2, 3, 5, 6, standing alone as a whole word."},
    {"id": "initial-letter", "name": "Initial-letter contractions",
     "note": "Dot 5, dots 4-5 or dots 4-5-6 before the first letter of the word."},
]

# word -> UEB cells (cross-check only; output is liblouis)
ALPHABETIC = {"but": "⠃", "can": "⠉", "do": "⠙", "every": "⠑", "from": "⠋", "go": "⠛", "have": "⠓",
              "just": "⠚", "knowledge": "⠅", "like": "⠇", "more": "⠍", "not": "⠝", "people": "⠏",
              "quite": "⠟", "rather": "⠗", "so": "⠎", "that": "⠞", "us": "⠥", "very": "⠧",
              "will": "⠺", "it": "⠭", "you": "⠽", "as": "⠵"}
STRONG_CONTRACTION = {"and": "⠯", "for": "⠿", "of": "⠷", "the": "⠮", "with": "⠾"}
STRONG_WORDSIGN = {"child": "⠡", "shall": "⠩", "this": "⠹", "which": "⠱", "out": "⠳", "still": "⠌"}
# groupsign -> (cell, example word)
STRONG_GROUPSIGN = {"ch": ("⠡", "chat"), "gh": ("⠣", "laugh"), "sh": ("⠩", "ship"), "th": ("⠹", "moth"),
                    "wh": ("⠱", "whip"), "ed": ("⠫", "red"), "er": ("⠻", "her"), "ou": ("⠳", "loud"),
                    "ow": ("⠪", "cow"), "st": ("⠌", "stop"), "ar": ("⠜", "car"), "ing": ("⠬", "sing")}
LOWER_WORDSIGN = {"be": "⠆", "enough": "⠢", "were": "⠶", "his": "⠦", "in": "⠔", "was": "⠴"}
INITIAL = {
    "5": ["day", "ever", "father", "here", "know", "lord", "mother", "name", "one", "part", "question",
          "right", "some", "time", "under", "work", "young", "there", "character", "through", "where",
          "ought"],
    "45": ["upon", "word", "these", "those", "whose"],
    "456": ["cannot", "had", "many", "spirit", "their", "world"],
}
PREFIX = {"5": "⠐", "45": "⠘", "456": "⠸"}
# initial-letter contraction -> the cell after the prefix (the word's first letter or groupsign)
INITIAL_SECOND = {"there": "⠮", "character": "⠡", "through": "⠹", "where": "⠱", "ought": "⠳",
                  "these": "⠮", "those": "⠹", "whose": "⠱", "their": "⠮"}


def grade2() -> tuple[dict, list[str]]:
    entries, skipped = [], []

    def word_entry(word, cat, expect, **extra):
        g2, g1 = tr(G2, word), tr(G1, word)
        if g2 == g1:
            skipped.append(f"{word} ({cat}): liblouis does not contract it")
            return
        assert g2 == expect, f"{word}: liblouis {g2} != UEB {expect}"
        entries.append({"word": word, "braille": g2, "dots": dots(g2), "category": cat,
                        "uncontracted": g1, **extra})

    for w, e in ALPHABETIC.items():
        word_entry(w, "alphabetic-wordsign", e)
    for w, e in STRONG_CONTRACTION.items():
        word_entry(w, "strong-contraction", e)
    for w, e in STRONG_WORDSIGN.items():
        word_entry(w, "strong-wordsign", e)
    for grp, (cell, example) in STRONG_GROUPSIGN.items():
        g2, g1 = tr(G2, example), tr(G1, example)
        if g2 == g1 or cell not in g2:
            skipped.append(f"{grp} (strong-groupsign): '{example}' is {g2}, no {cell}")
            continue
        entries.append({"word": grp, "braille": cell, "dots": dots(cell), "category": "strong-groupsign",
                        "example": {"word": example, "braille": g2, "dots": dots(g2), "uncontracted": g1}})
    for w, e in LOWER_WORDSIGN.items():
        word_entry(w, "lower-wordsign", e)
    for pre, words in INITIAL.items():
        for w in words:
            second = INITIAL_SECOND.get(w, tr(G1, w[0]))
            word_entry(w, "initial-letter", PREFIX[pre] + second, prefixDots=pre)

    return {
        "title": "Braille contractions (UEB grade 2)",
        "code": "UEB",
        "grade": 2,
        "generator": {"tool": "liblouis", "version": louis.version(), "tables": ",".join(G2)},
        "source": "liblouis",
        "dotsFormat": "one string per cell listing its raised dots, e.g. '125' = dots 1, 2 and 5",
        "categories": CATEGORIES,
        "entries": entries,
    }, skipped


def main() -> None:
    out = Path(sys.argv[1] if len(sys.argv) > 1 else "content/tutorials")
    out.mkdir(parents=True, exist_ok=True)
    g1 = grade1()
    g2, skipped = grade2()
    for name, data in (("braille-g1.json", g1), ("braille-g2.json", g2)):
        (out / name).write_text(json.dumps(data, ensure_ascii=False, indent=1) + "\n", encoding="utf-8")
    print(f"g1: {len(g1['letters'])} letters, {len(g1['numbers'])} numbers, "
          f"{len(g1['indicators'])} indicators, {len(g1['punctuation'])} punctuation")
    print(f"g2: {len(g2['entries'])} entries; skipped {len(skipped)}")
    for s in skipped:
        print("  skipped:", s)


if __name__ == "__main__":
    main()
